import sys

def min_tunnel_cost(planets):
    def find(parent, i):
        if parent[i] == i:
            return i
        parent[i] = find(parent, parent[i])
        return parent[i]

    def union(parent, rank, x, y):
        rootX = find(parent, x)
        rootY = find(parent, y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1

    n = len(planets)
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            dx = abs(planets[i][0] - planets[j][0])
            dy = abs(planets[i][1] - planets[j][1])
            dz = abs(planets[i][2] - planets[j][2])
            cost = min(dx, dy, dz)
            edges.append((cost, i, j))

    edges.sort()
    parent = list(range(n))
    rank = [0] * n
    mst_cost = 0
    mst_edges = 0

    for cost, u, v in edges:
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            mst_cost += cost
            mst_edges += 1
            if mst_edges == n - 1:
                break

    return mst_cost

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().splitlines()
    N = int(data[0])
    planets = [[int(x) for x in data[i+1].split()] for i in range(N)]
    print(min_tunnel_cost(planets))
